function updateOffset(){const e=Number(range.value), R=5.15, h=20, V=91975.16, A=2*R*R*Math.acos(e/(2*R))-(e/2)*Math.sqrt(4*R*R-e*e), delta=2*h*(Math.PI*R*R-A), iou=(2*V-delta)/(2*V+delta), gap=.15-e;
document.querySelector('#offset-value').textContent=e.toFixed(2)+' mm';document.querySelector('#gap-value').textContent=gap.toFixed(2)+' mm';document.querySelector('#iou-value').textContent=iou.toFixed(5);const passed=Math.round(gap*100)>=5;const status=document.querySelector('#gap-status');status.textContent=extra[locale][passed?'pass':'fail'];status.classList.toggle('pass',passed); const x=210+e/.14*10;document.querySelector('#shaft-circle').setAttribute('cx',x);document.querySelector('#shaft-axis').setAttribute('cx',x);}
range.addEventListener('input',()=>updateOffset());
function stopPlaying(){clearInterval(playing);playing=null;document.querySelector('#play-offset').textContent=extra[locale].play;}
