Object.assign(extra.en,{gaKicker:'SUBMITTED GRAPHICAL ABSTRACT',gaTitle:'The paper at a glance',gaIntro:'The graphical abstract from the submitted manuscript traces the relationship between an explicit requirement, a CAD revision and its paired diagnostic record.',gaCaption:'The submitted graphical abstract. Click to open the figure at full size. The cad15 example is a low-overlap case; the static high-IoU observations are a separate result.',mapTitle:'Where Hard-CAD fits',mapIntro:'A map of complementary ideas, not a ranking: select a research node to see its role and how it relates to the submitted manuscript.',nodeBench:'Geometric and feature evaluation',nodeTests:'Executable requirement tests',nodeCit:'Constraint intent and repair',nodeHard:'Contract + paired evidence + replay',nodeGen:'Local mating interface checks',nodeTrace:'Geometry preservation and repair',nodeFutureTitle:'Future research',nodeFuture:'Binding, history and physical checks',nodeRead:'Explore the method ↓',mapNote:'Connections indicate conceptual relationships described in the paper; they do not imply a historical lineage, direct comparison, or measured superiority.',designTitle:'From an engineering question to a replayable record',designIntro:'Follow the design decisions that make a change interpretable. Each stage adds information needed by the next.',designPlay:'▶ Play the sequence',designPause:'Ⅱ Pause',stage1:'Specify the requirement',stage1s:'source · entity · frame · units · bound',stage2:'Measure the geometry',stage2s:'operator · state · value · status',stage3:'Pair the same requirement',stage3s:'initial → revised · identical contract',stage4:'Explain and replay',stage4s:'local change · global change · hashes',designFoot:'A paired record is a join by requirement identity. Its value comes from explicit inputs, availability semantics and replay—not from a new pairing algorithm.'});
Object.assign(extra.zh,{gaKicker:'最终投稿图形摘要',gaTitle:'一图读懂论文',gaIntro:'投稿图形摘要将明确的设计要求、CAD 修订和配对诊断记录连接起来。',gaCaption:'来自投稿版本的图形摘要。点击查看大图。cad15 属于低重合度案例；静态高 IoU 缺陷是另一项独立结果。',mapTitle:'Hard-CAD 在研究版图中的位置',mapIntro:'这是一张互补研究关系图，而非排名。选择节点，查看其研究方向及与投稿论文的关系。',nodeBench:'几何与特征评估',nodeTests:'可执行要求检查',nodeCit:'约束意图与修复',nodeHard:'契约 + 配对证据 + 重放',nodeGen:'局部装配接口检查',nodeTrace:'几何保持与修复',nodeFutureTitle:'未来研究',nodeFuture:'语义绑定、历史记录与物理检查',nodeRead:'查看方法 ↓',mapNote:'连线表示论文讨论的概念关系，并不表示历史传承、直接对比或已证明的优劣。',designTitle:'从工程问题到可重放的诊断记录',designIntro:'沿着设计过程，逐步查看每项决策如何让修改变得可解释。',designPlay:'▶ 播放过程',designPause:'Ⅱ 暂停',stage1:'定义要求',stage1s:'来源 · 对象 · 坐标系 · 单位 · 边界',stage2:'测量几何',stage2s:'算子 · 状态 · 数值 · 可用性',stage3:'配对同一要求',stage3s:'初始 → 修订 · 相同契约',stage4:'解释并重放',stage4s:'局部变化 · 整体变化 · 哈希',designFoot:'配对记录是按要求标识进行的连接；其价值来自明确输入、可用性语义与重放，而非新的配对算法。'});
Object.assign(extra.ja,{gaKicker:'投稿したグラフィカルアブストラクト',gaTitle:'論文の全体像',gaIntro:'投稿した図は、明示的な要件、CAD 修訂、対応する診断記録の関係を示します。',gaCaption:'投稿版のグラフィカルアブストラクト。クリックで拡大します。cad15 は低 IoU の事例であり、静的な高 IoU 欠陥は別の結果です。',mapTitle:'研究分野における Hard-CAD',mapIntro:'補完的な研究を示す図です。ノードを選ぶと、それぞれの役割と投稿論文との関係を確認できます。',nodeBench:'幾何と特徴の評価',nodeTests:'実行可能な要件検査',nodeCit:'制約意図と修復',nodeHard:'契約・対応証拠・再実行',nodeGen:'局所的な接合面検査',nodeTrace:'形状保持と修復',nodeFutureTitle:'今後の研究',nodeFuture:'意味的対応・履歴・物理検査',nodeRead:'手法を見る ↓',mapNote:'線は論文で説明する概念上の関係を表し、研究の系譜や直接比較、優位性を意味しません。',designTitle:'工学的な問いから再実行可能な記録へ',designIntro:'変更を解釈可能にする設計上の判断を段階的に確認します。',designPlay:'▶ 過程を再生',designPause:'Ⅱ 一時停止',stage1:'要件を定義',stage1s:'出典・対象・座標系・単位・境界',stage2:'形状を測定',stage2s:'演算・状態・値・可用性',stage3:'同一要件を対応付け',stage3s:'初期 → 修訂・同一契約',stage4:'説明と再実行',stage4s:'局所変化・全体変化・ハッシュ',designFoot:'対応記録は要件 ID による結合です。価値は明示的入力、可用性の意味付け、再実行にあります。'});
Object.assign(extra.ko,{gaKicker:'제출한 그래픽 초록',gaTitle:'한눈에 보는 논문',gaIntro:'제출한 그래픽 초록은 명시적 요구사항, CAD 수정과 짝지은 진단 기록의 관계를 보여 줍니다.',gaCaption:'제출본 그래픽 초록입니다. 클릭하면 크게 볼 수 있습니다. cad15는 낮은 중첩 사례이며 정적인 높은 IoU 결함은 별도의 결과입니다.',mapTitle:'연구 지형 속 Hard-CAD',mapIntro:'순위가 아닌 상호 보완적인 연구 지도입니다. 노드를 선택하여 각 연구의 역할과 제출 논문과의 관계를 확인하세요.',nodeBench:'형상 및 특징 평가',nodeTests:'실행 가능한 요구사항 검사',nodeCit:'제약 의도와 수정',nodeHard:'계약 + 쌍별 증거 + 재실행',nodeGen:'국소 접합 인터페이스 검사',nodeTrace:'형상 보존과 수정',nodeFutureTitle:'향후 연구',nodeFuture:'의미 연결, 이력 및 물리 검사',nodeRead:'방법 살펴보기 ↓',mapNote:'연결선은 논문에서 설명한 개념적 관계이며 역사적 계보, 직접 비교 또는 입증된 우월성을 뜻하지 않습니다.',designTitle:'공학적 질문에서 재실행 가능한 기록으로',designIntro:'변화를 해석할 수 있게 만드는 설계 결정을 단계별로 살펴보세요.',designPlay:'▶ 과정 재생',designPause:'Ⅱ 일시 정지',stage1:'요구사항 정의',stage1s:'출처 · 대상 · 좌표계 · 단위 · 경계',stage2:'형상 측정',stage2s:'연산 · 상태 · 값 · 가용성',stage3:'동일 요구사항 연결',stage3s:'초기 → 수정 · 동일 계약',stage4:'설명과 재실행',stage4s:'국소 변화 · 전체 변화 · 해시',designFoot:'쌍별 기록은 요구사항 ID를 이용한 결합입니다. 가치는 명시적 입력, 가용성 의미 및 재실행에 있습니다.'});
const researchNodes={
bench:{url:'https://arxiv.org/abs/2605.10865',title:'BenchCAD',body:{en:'BenchCAD evaluates programmatic CAD with geometric, feature and edit-related measures. Its reported high-IoU blocked-bore example motivates attention to local requirements; Hard-CAD’s cad15 is a separate low-IoU revision.',zh:'BenchCAD 评估程序化 CAD 的几何、特征和修改表现；其高 IoU 通孔堵塞案例提示需要关注局部要求。Hard-CAD 的 cad15 是另一个低 IoU 修订案例。',ja:'BenchCAD はプログラム CAD の幾何、特徴、編集を評価します。高 IoU でも貫通穴が塞がる事例は局所要件への着目を促します。Hard-CAD の cad15 は別の低 IoU 修訂です。',ko:'BenchCAD는 프로그램 CAD의 형상, 특징 및 편집을 평가합니다. 높은 IoU에서도 관통 구멍이 막힌 사례는 국소 요구사항의 중요성을 보여 줍니다. Hard-CAD의 cad15는 별도의 낮은 IoU 수정 사례입니다.'}},
tests:{url:'https://arxiv.org/abs/2605.07807',title:'CADTests',body:{en:'CADTests provides executable, prompt-specific geometry and topology tests and uses test feedback for generation. Hard-CAD’s external transfer study uses native tests under a separate fixed-budget protocol.',zh:'CADTests 提供针对提示的可执行几何和拓扑测试，并利用测试反馈辅助生成。Hard-CAD 的外部迁移实验在独立的固定预算协议下使用其原生测试。',ja:'CADTests はプロンプトに対応した実行可能な幾何・位相テストと生成へのフィードバックを提供します。Hard-CAD の外部転移実験は別の固定予算条件でそのテストを使用します。',ko:'CADTests는 프롬프트별 실행 가능한 형상 및 위상 검사와 생성 피드백을 제공합니다. Hard-CAD의 외부 전이 실험은 별도의 고정 예산 프로토콜에서 원래 검사를 사용합니다.'}},
cit:{url:'https://arxiv.org/abs/2609.07434',title:'CIT-CAD',body:{en:'CIT-CAD organizes inferred design intent as a constraint tree and checks repairs against constraints. Hard-CAD focuses on declared operands and requirement-wise paired records under fixed checking conditions.',zh:'CIT-CAD 将推断的设计意图组织为约束树，并检查修复对约束的保持。Hard-CAD 则关注已声明的检查对象，以及固定条件下逐项配对的诊断记录。',ja:'CIT-CAD は推定した設計意図を制約ツリーとして構成し、修復後の制約を検査します。Hard-CAD は宣言された対象と固定条件下の要件別対応記録に焦点を当てます。',ko:'CIT-CAD는 추론된 설계 의도를 제약 트리로 구성하고 수정 후 제약을 검사합니다. Hard-CAD는 선언된 대상과 고정 조건에서 요구사항별 쌍 기록에 초점을 둡니다.'}},
gen:{url:'https://github.com/huggingface/cadgenbench/blob/33304cf771fc5639144b1df9611e347251052cf8/docs/metrics/interface_match.md',title:'CADGenBench',body:{en:'CADGenBench measures mating interfaces using declared keep-in and keep-out geometry. The paper compares its fixed-pose component with empty-region occupancy: 80/84 paired labels agree, with four differences arising from acceptance criteria.',zh:'CADGenBench 使用声明的保留和禁入区域评估装配接口。论文比较其固定姿态组件与空区占据检查：84 条配对标签有 80 条一致，四处差异来自验收条件。',ja:'CADGenBench は保持・禁止領域を使って接合面を評価します。論文では固定姿勢コンポーネントと空領域占有を比較し、84 件中 80 件が一致、4 件は合格基準の違いでした。',ko:'CADGenBench는 지정된 유지·금지 영역으로 접합 인터페이스를 평가합니다. 논문의 고정 자세 구성 요소 비교에서 84개 중 80개 전이 라벨이 일치했고 네 차이는 판정 기준에서 발생했습니다.'}},
trace:{url:'https://arxiv.org/abs/2608.03062',title:'TraceCAD',body:{en:'TraceCAD combines repair memory, localized search and paired preservation measures. Hard-CAD applies a fixed-frame volume analogue as a comparison and retains the identity of the declared region whose state changed.',zh:'TraceCAD 结合修复记忆、局部搜索和配对几何保持指标。Hard-CAD 使用固定坐标系的体积类比作为比较，并保留发生状态变化的声明区域标识。',ja:'TraceCAD は修復メモリ、局所探索、対応する形状保持指標を組み合わせます。Hard-CAD は固定座標の体積類似指標を比較に用い、状態が変化した宣言領域の ID を保持します。',ko:'TraceCAD는 수정 메모리, 국소 탐색과 쌍별 형상 보존 지표를 결합합니다. Hard-CAD는 고정 좌표 체적 유사 지표를 비교에 사용하고 상태가 바뀐 선언 영역의 식별자를 보존합니다.'}},
hard:{url:'#design-rationale',title:'Hard-CAD',body:{en:'A contract binds requirement identity to operands, frame, units, state and bound. Paired measurements retain unavailable states and local/global changes, then bind the record to executable replay.',zh:'契约将要求标识与对象、坐标系、单位、状态和边界绑定。配对测量保留不可用状态以及局部、全局变化，并将记录连接到可执行重放。',ja:'契約は要件 ID を対象、座標系、単位、状態、境界に結び付けます。対応測定は測定不能状態と局所・全体の変化を保持し、再実行につなげます。',ko:'계약은 요구사항 식별자를 대상, 좌표계, 단위, 상태 및 경계에 연결합니다. 쌍별 측정은 측정 불가 상태와 국소·전체 변화를 보존하고 실행 재현에 연결합니다.'}},
future:{url:'#futureTitleAnchor',title:'Future research',body:{en:'The manuscript proposes independently specified entity and feature references, matched repair studies with withheld checks, and richer state models for rotation, deformation, loads and manufacturing.',zh:'论文提出使用独立指定的实体与特征参考，开展包含未披露检查的匹配修复实验，并为旋转、变形、载荷和制造建立更丰富的状态模型。',ja:'論文は独立に指定された実体・特徴の参照、未開示検査を含む対応修復実験、回転・変形・荷重・製造の状態モデルを次の課題として挙げています。',ko:'논문은 독립적으로 지정된 개체·특징 참조, 비공개 검사를 포함한 대응 수정 실험, 회전·변형·하중·제조를 위한 확장된 상태 모델을 제안합니다.'}}
};
researchNodes.future.url='#evidence-explorer';
const designDescriptions={
en:['A requirement ID and declared entities, frame, units, state or path, operator and bound define what can be checked.','Use established Boolean, distance or prescribed-motion operations with valid operands. Store the value, unit and whether the measurement is available.','Join the same requirement across initial and revised artifacts under fixed checking conditions; duplicate IDs and changed contract hashes are rejected.','Show the local transition beside global extra and missing material; bind inputs and configuration to hashes so the checks can be replayed.'],
zh:['要求标识以及声明的对象、坐标系、单位、状态或路径、算子和边界，共同定义可检查的内容。','在有效输入上使用既有的布尔、距离或指定运动检查，记录数值、单位和测量是否可用。','在固定检查条件下连接初始与修订中的同一要求；重复标识和变更过的契约哈希会被拒绝。','将局部状态变化与全局多余及缺失材料并列，并以哈希绑定输入和配置，支持重新执行检查。'],
ja:['要件 ID、宣言された対象、座標系、単位、状態や経路、演算、境界により検査内容を定義します。','有効な入力に既存のブール、距離、指定運動の演算を適用し、値、単位、測定可能性を保存します。','固定された検査条件下で初期版と修訂版の同一要件を結合し、重複 ID や変更された契約ハッシュを拒否します。','局所状態の変化と全体の余剰・欠落材料を併記し、入力と設定をハッシュに結び付けて再実行します。'],
ko:['요구사항 ID와 선언된 대상, 좌표계, 단위, 상태 또는 경로, 연산 및 경계가 검사 대상을 정의합니다.','유효한 입력에 기존 불리언, 거리 또는 지정 운동 연산을 적용하고 값, 단위 및 측정 가능 상태를 기록합니다.','고정된 검사 조건에서 초기와 수정 버전의 동일 요구사항을 결합하고 중복 ID와 변경된 계약 해시를 거부합니다.','국소 상태 변화와 전체 초과·누락 재료를 함께 표시하고 입력과 설정을 해시에 연결해 재실행합니다.']};
const sourceLabels={en:'Read original source ↗',zh:'阅读原始文献 ↗',ja:'原典を読む ↗',ko:'원문 보기 ↗'};
let activeResearch='hard',activeStage=0,designTimer=null;
function showResearch(key){activeResearch=key;const data=researchNodes[key];document.querySelectorAll('[data-node]').forEach(button=>{const active=button.dataset.node===key;button.classList.toggle('active',active);button.setAttribute('aria-pressed',String(active))});document.querySelector('#node-title').textContent=key==='future'?extra[locale].nodeFutureTitle:data.title;document.querySelector('#node-description').textContent=data.body[locale];const link=document.querySelector('#node-source');link.href=data.url;link.textContent=key==='hard'?extra[locale].nodeRead:key==='future'?extra[locale].futureTitle:sourceLabels[locale];if(data.url.startsWith('https:')){link.target='_blank';link.rel='noopener noreferrer'}else{link.removeAttribute('target');link.removeAttribute('rel')}}
function showDesign(index){activeStage=index;document.querySelectorAll('[data-stage]').forEach(button=>{const active=Number(button.dataset.stage)===index;button.classList.toggle('active',active);button.setAttribute('aria-pressed',String(active))});document.querySelector('.design-screen').dataset.step=index;document.querySelector('#design-count').textContent=`0${index+1} / 04`;document.querySelector('#design-stage-title').textContent=extra[locale][`stage${index+1}`];document.querySelector('#design-stage-description').textContent=designDescriptions[locale][index];document.querySelector('#screen-label').textContent=['q · contract','q · measurement','q · v₀ → v₁','q · replay'][index]}
function stopDesign(){clearInterval(designTimer);designTimer=null;document.querySelector('#design-play').textContent=extra[locale].designPlay}
document.querySelectorAll('[data-node]').forEach(button=>button.addEventListener('click',()=>showResearch(button.dataset.node)));
document.querySelectorAll('[data-stage]').forEach(button=>button.addEventListener('click',()=>{stopDesign();showDesign(Number(button.dataset.stage))}));
document.querySelector('#design-play').addEventListener('click',()=>{if(designTimer){stopDesign();return}showDesign(0);document.querySelector('#design-play').textContent=extra[locale].designPause;designTimer=setInterval(()=>{if(activeStage===3){stopDesign();return}showDesign(activeStage+1)},2200)});
const beforeResearchLocale=setLocale;setLocale=function(lang){beforeResearchLocale(lang);showResearch(activeResearch);showDesign(activeStage);document.querySelector('#design-play').textContent=designTimer?extra[lang].designPause:extra[lang].designPlay};setLocale('en');
